import os, sys, zlib, itertools

SRC='/app/corrupted'; DST='/app/recovered'
os.makedirs(DST, exist_ok=True)
POLY=0xEDB88320
TABLE=[]
for i in range(256):
    c=i
    for _ in range(8):
        c=(c>>1)^(POLY if c&1 else 0)
    TABLE.append(c)

def rev_step(sp,b):
    for j in range(256):
        hi=sp^TABLE[j]
        if hi>>24==0:
            st=((hi<<8)|(j^b))&0xffffffff
            if ((st>>8)^TABLE[(st^b)&0xff])&0xffffffff==sp:
                return st
    raise ValueError('norev')

def fwd(state,bs):
    for b in bs:
        state=((state>>8)^TABLE[(state^b)&0xff])&0xffffffff
    return state

def rev(state,bs):
    for b in reversed(bs):
        state=rev_step(state,b)
    return state

ALPHA=set(b'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz')
def is_type(t): return len(t)==4 and all(b in ALPHA for b in t)

def crc_cands(r):
    res=set(); need=4-len(r)
    pos=[i for i,b in enumerate(r) if b==0x0a]
    if need<0 or need>len(pos): return res
    for combo in itertools.combinations(pos,need):
        out=bytearray(); cs=set(combo)
        for i,b in enumerate(r):
            if i in cs: out.append(0x0d)
            out.append(b)
        res.add(bytes(out))
    return res

def solve_data(seg,k,ctype,targets):
    pos=[i for i,b in enumerate(seg) if b==0x0a]
    n=len(pos)
    if k<0 or k>n: return None
    tint={int.from_bytes(t,'big')^0xffffffff for t in targets}
    segs=[]; last=0
    for p in pos:
        segs.append(bytes(seg[last:p])); last=p
    segs.append(bytes(seg[last:]))
    if k==0:
        d=bytes(seg)
        st=fwd(fwd(0xffffffff,ctype),d)
        if (st^0xffffffff) in tint: return d
        return None
    half=n//2
    start=fwd(0xffffffff,ctype); start=fwd(start,segs[0])
    fwdmap={}
    for bits in range(1<<half):
        if bin(bits).count('1')>k: continue
        s=start
        for j in range(half):
            if bits>>j&1: s=fwd(s,b'\x0d')
            s=fwd(s,b'\x0a')
            if j!=half-1: s=fwd(s,segs[j+1])
        if s not in fwdmap: fwdmap[s]=bits
    nb=n-half
    for bits2 in range(1<<nb):
        if bin(bits2).count('1')>k: continue
        for tf in tint:
            s=tf
            s=rev(s,segs[n])
            for j in range(n-1,half-1,-1):
                s=rev(s,b'\x0a')
                if bits2>>(j-half)&1: s=rev(s,b'\x0d')
                s=rev(s,segs[j])
            if s in fwdmap:
                b1=fwdmap[s]
                if bin(b1).count('1')+bin(bits2).count('1')!=k: continue
                out=bytearray(segs[0])
                for j in range(n):
                    bit=(b1>>j&1) if j<half else (bits2>>(j-half)&1)
                    if bit: out.append(0x0d)
                    out.append(0x0a); out+=segs[j+1]
                return bytes(out)
    return None

def recover(data):
    if data[:4]!=b'\x89PNG': return None
    def dfs(c,chunks,depth):
        if c==len(data):
            return chunks if (chunks and chunks[-1][0]==b'IEND') else None
        if depth>50 or c+8>len(data): return None
        L=int.from_bytes(data[c:c+4],'big')
        ctype=bytes(data[c+4:c+8])
        if not is_type(ctype) or L>20000000: return None
        dstart=c+8
        for dend in range(min(dstart+L,len(data)),dstart-1,-1):
            seg=data[dstart:dend]
            k=L-len(seg)
            if k<0 or k>seg.count(0x0a): continue
            for crclen in range(4,1,-1):
                q=dend+crclen
                if q>len(data): break
                if q==len(data):
                    if ctype!=b'IEND': continue
                elif not (q+8<=len(data) and is_type(data[q+4:q+8])):
                    continue
                targets=crc_cands(bytes(data[dend:q]))
                if not targets: continue
                sol=solve_data(seg,k,ctype,targets)
                if sol is None: continue
                crc=zlib.crc32(ctype+sol)&0xffffffff
                r=dfs(q,chunks+[(ctype,sol,crc)],depth+1)
                if r is not None: return r
        return None
    res=dfs(7,[],0)
    if res is None: return None
    out=bytearray(b'\x89PNG\r\n\x1a\n')
    idat=b''
    ihdr=None
