    # verify
    w,h,bd,ct=ihdr[0:4].hex(),ihdr[4:8],ihdr[8],ihdr[9]
    w=int.from_bytes(bytes.fromhex(w),'big'); h=int.from_bytes(ihdr[4:8],'big')
    raw=zlib.decompress(idat)
    return bytes(out), (w,h,len(raw))

